from pathlib import Path
from playwright.sync_api import sync_playwright,expect
p=argparse.ArgumentParser();p.add_argument('--url',required=True);p.add_argument('--report',required=True,type=Path);args=p.parse_args();checks=[]
source='Hi Sam, I just wanted to let you know that the meeting room is booked for Friday at 3. The thing is, I still need to confirm whether the projector is available, so for now please don\'t send the invitation yet. I was also wondering if you could send me the attendee list by tomorrow noon. If the projector is unavailable, we may need to use room B instead. Thanks!'
output='Hi Sam, the meeting room is booked for Friday at 3. I still need to confirm whether the projector is available, so please don\'t send the invitation yet. Could you send me the attendee list by tomorrow noon? If the projector is unavailable, we may need to use room B instead. Thanks!'
